# change: empty_receptacle_memory_v3 (p-alfworld-2-1)
def applies(view):
    return True


def alf_after_step(event, state):
    st = state if isinstance(state, dict) else {}
    recept = {}
    for k, v in (st.get("recept") or {}).items():
        if isinstance(v, dict):
            recept[k[:120]] = {"n": int(v.get("n", 0)),
                               "last_obs": str(v.get("last_obs", ""))[:200]}
    a = event.get("action") or ""
    if isinstance(a, str) and a.startswith("go to ") and len(a) <= 120:
        o = (event.get("observation") or "").strip()
        e = recept.get(a)
        if e is None:
            recept[a] = {"n": 1, "last_obs": o[:200]}
        else:
            e["n"] = e["n"] + 1
            e["last_obs"] = o[:200]
    return {"step": st.get("step", -1) + 1, "recept": recept}


def alf_before_step(view, state):
    if not isinstance(state, dict):
        return {"fields": {}, "discourage": []}
    recept = state.get("recept") or {}
    empty, disc = [], []
    for cmd, e in sorted(recept.items()):
        if not isinstance(e, dict):
            continue
        obs = str(e.get("last_obs", ""))
        if "you see nothing" not in obs:
            continue
        n = int(e.get("n", 0))
        if n >= 2:
            empty.append("%s (%d visits, empty)" % (cmd, n))
            disc.append(cmd)
    warns = []
    if empty:
        warns.append(("Empty-on-last-visit receptacles visited 2+ times: "
                      + "; ".join(empty))[:200])
    n = state.get("step", -1) + 1
    if n >= 12:
        room = (view.get("initial_observation") or "").lower()
        adm = view.get("admissible_commands") or []
        room_types = set()
        for w in room.replace(",", " ").replace(".", " ").split():
            room_types.add(w)
        unvis = []
        for c in adm:
            if not (isinstance(c, str) and c.startswith("go to ")):
                continue
            if c in recept:
                continue
            words = c[6:].split()
            if len(words) >= 2 and words[0] in room_types:
                unvis.append(c)
            if len(unvis) >= 8:
                break
        if len(unvis) >= 3:
            warns.append(("Never-visited 'go to' targets in this room so far: "
                          + ", ".join(c[6:] for c in unvis))[:200])
    if warns:
        return {"fields": {"warnings": warns[:3]}, "discourage": disc[:10]}
    return {"fields": {}, "discourage": []}
